INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_04','V501','老师',4,'登记系统需要留存纸质复印件，楼下打印店可以当场复印。','dēng jì xì tǒng xū yào liú cún zhǐ zhì fù yìn jiàn， lóu xià dǎ yìn diàn kě yǐ dāng chǎng fù yìn。','Hệ thống đăng ký cần lưu bản sao giấy, tiệm photo dưới lầu có thể in ngay tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_05','V501','阮明',5,'那我先下楼复印，回来还需要填写什么登记表格吗？','nà wǒ xiān xià lóu fù yìn， huí lái hái xū yào tián xiě shén me dēng jì biǎo gé ma？','Vậy em xuống photo trước, quay lại còn phải điền thêm mẫu đăng ký nào nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_06','V501','老师',6,'要填入境信息登记表，写明抵达日期、居住宿舍房间号。','yào tián rù jìng xìn xī dēng jì biǎo， xiě míng dǐ dá rì qī、 jū zhù sù shě fáng jiān hào。','Cần điền tờ đăng ký thông tin nhập cảnh, ghi rõ ngày đến và số phòng ký túc xá đang ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_07','V501','阮明',7,'登记完成后，才可以预约出入境办居留许可对吗？','dēng jì wán chéng hòu， cái kě yǐ yù yuē chū rù jìng bàn jū liú xǔ kě duì ma？','Đăng ký xong rồi mới được hẹn lịch làm giấy phép cư trú ở phòng xuất nhập cảnh đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_08','V501','老师',8,'没错，未完成校内登记，出入境大厅不会受理签证申请。','méi cuò， wèi wán chéng xiào nèi dēng jì， chū rù jìng dà tīng bú huì shòu lǐ qiān zhèng shēn qǐng。','Đúng vậy, nếu chưa hoàn tất đăng ký trong trường thì bên xuất nhập cảnh sẽ không tiếp nhận hồ sơ xin visa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_09','V501','阮明',9,'好，我马上复印材料，十分钟回来办理登记。','hǎo， wǒ mǎ shàng fù yìn cái liào， shí fēn zhōng huí lái bàn lǐ dēng jì。','Dạ vâng, em đi photo tài liệu ngay, mười phút nữa em quay lại làm đăng ký.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT502','SV1','提交护照、录取材料申请首次居留许可',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V502','SIT502','P1','suon_se','chinh_thuc',NULL,'首次学生居留许可全套材料缺一不可，缺少任意一项都会直接退回不予受理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_01','V502','阮明',1,'您好，我是新生留学生，来递交首次居留许可申请材料。','nín hǎo， wǒ shì xīn shēng liú xué shēng， lái dì jiāo shǒu cì jū liú xǔ kě shēn qǐng cái liào。','Xin chào, tôi là du học sinh mới, đến để nộp hồ sơ xin cấp giấy phép cư trú lần đầu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_02','V502','工作人员',2,'依次递交护照、录取通知书、体检报告、住宿登记单哦。','yī cì dì jiāo hù zhào、 lù qǔ tōng zhī shū、 tǐ jiǎn bào gào、 zhù sù dēng jì dān ó。','Anh/chị nộp lần lượt hộ chiếu, giấy báo nhập học, giấy khám sức khỏe và giấy đăng ký chỗ ở nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_03','V502','阮明',3,'全部材料都整理齐全，一式两份已经分好。','quán bù cái liào dōu zhěng lǐ qí quán， yī shì liǎng fèn yǐ jīng fēn hǎo。','Toàn bộ hồ sơ đã được sắp xếp đầy đủ, mỗi loại đã chuẩn bị hai bản.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_04','V502','工作人员',4,'我核对一遍，信息匹配无误，给你一张受理回执。','wǒ hé duì yī biàn， xìn xī pǐ pèi wú wù， gěi nǐ yī zhāng shòu lǐ huí zhí。','Tôi kiểm tra lại một lượt, thông tin khớp hết, đây là phiếu biên nhận cho anh/chị.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_05','V502','阮明',5,'大概几个工作日能拿到办好的居留贴纸呢？','dà gài jǐ gè gōng zuò rì néng ná dào bàn hǎo de jū liú tiē zhǐ ne？','Khoảng mấy ngày làm việc thì tôi có thể nhận được tem cư trú đã làm xong ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_06','V502','工作人员',6,'标准七个工作日，加急业务三个工作日办结。','biāo zhǔn qī gè gōng zuò rì， jiā jí yè wù sān gè gōng zuò rì bàn jié。','Bình thường là bảy ngày làm việc, làm nhanh thì ba ngày làm việc là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_07','V502','阮明',7,'取件可以凭回执代领，还是必须本人到场？','qǔ jiàn kě yǐ píng huí zhí dài lǐng， hái shì bì xū běn rén dào chǎng？','Khi nhận giấy tờ, tôi có thể nhờ người khác cầm biên nhận đến lấy hộ được không, hay bắt buộc phải đích thân đến?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_08','V502','工作人员',8,'本人携带回执、身份证（护照）才能领取证件。','běn rén xié dài huí zhí、 shēn fèn zhèng （hù zhào） cái néng lǐng qǔ zhèng jiàn。','Phải chính chủ mang theo biên nhận và giấy tờ tùy thân (hộ chiếu) mới được nhận giấy tờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_09','V502','阮明',9,'清楚了，辛苦您受理我的签证材料！','qīng chǔ le， xīn kǔ nín shòu lǐ wǒ de qiān zhèng cái liào！','Tôi rõ rồi, cảm ơn anh/chị đã vất vả tiếp nhận hồ sơ visa của tôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT503','SV1','体检不合格，需要重新预约出入境体检',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V503','SIT503','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生签证专用体检必须在出入境指定医院完成，体检不合格无法提交居留申请，复查需全额自费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_01','V503','阮明',1,'医生，我昨天拿到出入境体检报告，被告知体检不合格。','yī shēng， wǒ zuó tiān ná dào chū rù jìng tǐ jiǎn bào gào， bèi gào zhī tǐ jiǎn bù hé gé。','Bác sĩ ơi, hôm qua em nhận được báo cáo khám sức khỏe xuất nhập cảnh, bị thông báo là không đạt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_02','V503','校医',2,'我看看报告，是肝功能指标临时偏高，无法提交签证使用。','wǒ kàn kàn bào gào， shì gān gōng néng zhǐ biāo lín shí piān gāo， wú fǎ tí jiāo qiān zhèng shǐ yòng。','Để tôi xem báo cáo, chỉ số chức năng gan của em tạm thời cao hơn bình thường, không thể dùng để nộp visa được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_03','V503','阮明',3,'那这种情况只能重新全套体检吗，没有补救办法？','nà zhè zhǒng qíng kuàng zhǐ néng chóng xīn quán tào tǐ jiǎn ma， méi yǒu bǔ jiù bàn fǎ？','Vậy trường hợp này chỉ có cách khám lại toàn bộ thôi ạ, không có cách nào khắc phục sao?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_04','V503','校医',4,'需要间隔一周清淡饮食后重新预约，只复查异常项目不行嘛。','xū yào jiàn gé yī zhōu qīng dàn yǐn shí hòu chóng xīn yù yuē， zhǐ fù chá yì cháng xiàng mù bù xíng ma。','Em cần ăn uống thanh đạm trong một tuần rồi hẹn khám lại, chứ không thể chỉ khám riêng mục bất thường đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_05','V503','阮明',5,'重新体检还要再交一次全套体检费用对吧？','chóng xīn tǐ jiǎn hái yào zài jiāo yī cì quán tào tǐ jiǎn fèi yòng duì ba？','Khám lại thì em phải đóng lại toàn bộ chi phí khám sức khỏe đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_06','V503','校医',6,'是的，出入境指定体检中心复查需要全额重新缴费。','shì de， chū rù jìng zhǐ dìng tǐ jiǎn zhōng xīn fù chá xū yào quán é chóng xīn jiǎo fèi。','Đúng vậy, khám lại tại trung tâm khám sức khỏe chỉ định của xuất nhập cảnh thì phải đóng lại toàn bộ phí.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_07','V503','阮明',7,'一周后直接线上预约体检中心就能重新检测吗？','yī zhōu hòu zhí jiē xiàn shàng yù yuē tǐ jiǎn zhōng xīn jiù néng chóng xīn jiǎn cè ma？','Một tuần sau em chỉ cần đặt lịch online với trung tâm khám sức khỏe là có thể khám lại luôn phải không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_08','V503','校医',8,'线上预约后带旧报告，方便医生对比两次检测数据。','xiàn shàng yù yuē hòu dài jiù bào gào， fāng biàn yī shēng duì bǐ liǎng cì jiǎn cè shù jù。','Đặt lịch online xong thì mang theo báo cáo cũ, để bác sĩ tiện so sánh kết quả hai lần khám.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_09','V503','阮明',9,'我记好时间调整作息，下周再来做全套体检。','wǒ jì hǎo shí jiān tiáo zhěng zuò xī， xià zhōu zài lái zuò quán tào tǐ jiǎn。','Em ghi nhớ thời gian, điều chỉnh sinh hoạt lại, tuần sau em sẽ đến khám tổng quát lại.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT504','SV1','忘记携带境外录取通知书原件，无法提交签证材料',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V504','SIT504','P1','that_bai_nhe','chinh_thuc',NULL,'出入境办理居留许可严格核验纸质原件，电子照片、复印件均不具备受理效力，必须线下现场核验。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_01','V504','阮明',1,'您好，我今天过来递交居留许可申请材料。','nín hǎo， wǒ jīn tiān guò lái dì jiāo jū liú xǔ kě shēn qǐng cái liào。','Xin chào, hôm nay tôi đến để nộp hồ sơ xin cấp giấy phép cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_02','V504','工作人员',2,'麻烦出示境外院校发放的纸质录取通知书原件。','má fán chū shì jìng wài yuàn xiào fā fàng de zhǐ zhì lù qǔ tōng zhī shū yuán jiàn。','Phiền anh/chị xuất trình bản gốc giấy báo nhập học do trường ở nước ngoài cấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_03','V504','阮明',3,'糟糕，我只带了复印件，原件放在宿舍忘记带来了啊。','zāo gāo， wǒ zhǐ dài le fù yìn jiàn， yuán jiàn fàng zài sù shè wàng jì dài lái le a。','Chết rồi, tôi chỉ mang theo bản sao thôi, bản gốc để ở ký túc xá quên mang theo mất rồi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_04','V504','工作人员',4,'签证审核必须核验原件，复印件不能单独作为受理材料。','qiān zhèng shěn hé bì xū hé yàn yuán jiàn， fù yìn jiàn bù néng dān dú zuò wéi shòu lǐ cái liào。','Khi xét duyệt visa bắt buộc phải kiểm tra bản gốc, bản sao không thể dùng làm hồ sơ tiếp nhận riêng lẻ được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_05','V504','阮明',5,'手机里存有原件高清照片，能不能先帮我受理后续补交？','shǒu jī lǐ cún yǒu yuán jiàn gāo qīng zhào piān， néng bù néng xiān bāng wǒ shòu lǐ hòu xù bǔ jiāo？','Trong điện thoại tôi có lưu ảnh chụp bản gốc độ nét cao, anh/chị có thể tiếp nhận trước rồi cho tôi bổ sung sau được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_06','V504','工作人员',6,'系统硬性规定，材料不齐无法建档，只能改天带原件再来。','xì tǒng yìng xìng guī dìng， cái liào bù qí wú fǎ jiàn dàng， zhǐ néng gǎi tiān dài yuán jiàn zài lái。','Hệ thống quy định cứng, hồ sơ không đầy đủ thì không thể lập hồ sơ được, chỉ có thể hẹn hôm khác mang bản gốc đến thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_07','V504','阮明',7,'那我明天一早带齐全部原件再来窗口办理可以吗？','nà wǒ míng tiān yī zǎo dài qí quán bù yuán jiàn zài lái chuāng kǒu bàn lǐ kě yǐ ma？','Vậy sáng mai tôi mang đầy đủ bản gốc đến quầy làm thủ tục được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_08','V504','工作人员',8,'明天正常上班，上午人少，建议早点过来排队。','míng tiān zhèng cháng shàng bān， shàng wǔ rén shǎo， jiàn yì zǎo diǎn guò lái pái duì。','Mai làm việc bình thường, buổi sáng ít người, anh/chị nên đến sớm để xếp hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_09','V504','阮明',9,'好的，实在抱歉漏带关键证件，耽误您工作了。','hǎo de， shí zài bào qiàn lòu dài guān jiàn zhèng jiàn， dān wù nín gōng zuò le。','Vâng, thật sự xin lỗi vì đã để thiếu giấy tờ quan trọng, làm phiền công việc của anh/chị.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT505','SV1','咨询留学生居留许可有效时长与入境截止规则',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V505','SIT505','P1','suon_se','ban_chinh_thuc',NULL,'学生居留许可最长与学制同步，到期断签属于非法滞留，会产生罚款并影响后续再次来华签证。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_01','V505','阮明',1,'警官您好，想咨询留学生居留许可的有效期相关规定。','jǐng guān nín hǎo， xiǎng zī xún liú xué shēng jū liú xǔ kě de yǒu xiào qī xiāng guān guī dìng。','Chào chú công an, tôi muốn hỏi về quy định thời hạn hiệu lực của giấy phép cư trú dành cho du học sinh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_02','V505','辅警',2,'居留时长和你的学制匹配，本科一般一次发放一年哦。','jū liú shí cháng hé nǐ de xué zhì pǐ pèi， běn kē yì bān yī cì fā fàng yī nián ó。','Thời hạn cư trú tương ứng với chương trình học của em, hệ đại học thường thì mỗi lần cấp là một năm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_03','V505','阮明',3,'如果寒暑假短期回国，在居留有效期内往返不受限制吧？','rú guǒ hán shǔ jià duǎn qī huí guó， zài jū liú yǒu xiào qī nèi wǎng fǎn bù shòu xiàn zhì ba？','Nếu về nước ngắn ngày vào dịp nghỉ hè, nghỉ đông thì trong thời hạn cư trú còn hiệu lực, việc đi lại không bị hạn chế đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_04','V505','辅警',4,'有效期内多次出入境无需额外报备，超期滞留会有处罚。','yǒu xiào qī nèi duō cì chū rù jìng wú xū é wài bào bèi， chāo qī zhì liú huì yǒu chǔ fá。','Trong thời hạn hiệu lực thì xuất nhập cảnh nhiều lần không cần báo cáo thêm, nhưng ở lại quá hạn sẽ bị xử phạt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_05','V505','阮明',5,'居留证到期前最晚多久要提交续办申请呢？','jū liú zhèng dào qī qián zuì wǎn duō jiǔ yào tí jiāo xù bàn shēn qǐng ne？','Trước khi thẻ cư trú hết hạn, chậm nhất là bao lâu thì phải nộp đơn xin gia hạn ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_06','V505','辅警',6,'建议提前三十天递交，预留审核时间避免断签。','jiàn yì tí qián sān shí tiān dì jiāo， yù liú shěn hé shí jiān bì miǎn duàn qiān。','Nên nộp trước ba mươi ngày, để dành thời gian xét duyệt, tránh bị gián đoạn visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_07','V505','阮明',7,'入境时签证上标注的最晚入境日期有什么约束？','rù jìng shí qiān zhèng shàng biāo zhù de zuì wǎn rù jìng rì qī yǒu shén me yuē shù？','Ngày nhập cảnh muộn nhất được ghi trên visa lúc nhập cảnh có ràng buộc gì không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_08','V505','辅警',8,'必须在标注日期前入境，逾期签证直接作废失效。','bì xū zài biāo zhù rì qī qián rù jìng， yú qī qiān zhèng zhí jiē zuò fèi shī xiào。','Bắt buộc phải nhập cảnh trước ngày ghi trên đó, visa quá hạn sẽ tự động mất hiệu lực luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_09','V505','阮明',9,'全部规则我记清楚了，非常感谢您细致讲解！','quán bù guī zé wǒ jì qīng chǔ le， fēi cháng gǎn xiè nín xì zhì jiǎng jiě！','Tôi đã nắm rõ hết các quy định rồi, cảm ơn chú đã giải thích cặn kẽ ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT506','SV1','学校统一代办居留签证，补交缺失的白底证件照',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V506','SIT506','P1','twist','tuy_y',NULL,'出入境签证证件照有统一尺寸、底色标准，照相馆会区分普通证件照与涉外签证专用照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_01','V506','老师',1,'阮明，学校统一代办居留签证，还差你的证件照没交。','ruǎn míng， xué xiào tǒng yí dài bàn jū liú qiān zhèng， hái chà nǐ de zhèng jiàn zhào méi jiāo。','Nguyễn Minh này, trường đang làm thủ tục visa cư trú tập trung, còn thiếu ảnh thẻ của em nữa đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_02','V506','阮明',2,'我上周交过一版照片，是尺寸不符合要求嘛？','wǒ shàng zhōu jiāo guò yī bǎn zhào piān， shì chǐ cùn bù fú hé yāo qiú ma？','Tuần trước em nộp một tấm ảnh rồi mà, hay là kích thước không đúng yêu cầu ạ?','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_03','V506','老师',3,'普通生活照不行，必须小二寸白底免冠证件照哈。','pǔ tōng shēng huó zhào bù xíng， bì xū xiǎo èr cùn bái dǐ miǎn guān zhèng jiàn zhào hā。','Ảnh chụp đời thường bình thường không được đâu, phải là ảnh thẻ 2x3 nền trắng không đội mũ nón cơ.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_04','V506','阮明',4,'楼下照相馆能拍符合出入境标准的签证照片吗？','lóu xià zhào xiàng guǎn néng pāi fú hé chū rù jìng biāo zhǔn de qiān zhèng zhào piān ma？','Tiệm chụp ảnh dưới lầu có chụp được ảnh visa đúng chuẩn xuất nhập cảnh không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_05','V506','老师',5,'可以，直接跟摄影师说办居留许可用，他知道规格。','kě yǐ， zhí jiē gēn shè yǐng shī shuō bàn jū liú xǔ kě yòng， tā zhī dào guī gé。','Được đó, em cứ nói thẳng với thợ chụp là chụp để làm giấy phép cư trú, họ biết quy cách rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_06','V506','阮明',6,'拍完下午送过来，还需要额外填写补充表格吗？','pāi wán xià wǔ sòng guò lái， hái xū yào é wài tián xiě bǔ chōng biǎo gé ma？','Chụp xong chiều em mang đến, còn phải điền thêm mẫu đơn bổ sung nào không thầy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_07','V506','老师',7,'只交纸质照片就行，其余信息系统里都有存档。','zhǐ jiāo zhǐ zhì zhào piān jiù xíng， qí yú xìn xī xì tǒng lǐ dōu yǒu cún dàng。','Chỉ cần nộp ảnh giấy thôi, thông tin còn lại hệ thống đã lưu sẵn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_08','V506','阮明',8,'好嘞，我现在下楼拍照，很快送过来给您。','hǎo lei， wǒ xiàn zài xià lóu pāi zhào， hěn kuài sòng guò lái gěi nín。','Dạ được, em xuống chụp ảnh ngay đây, lát nữa mang lên cho thầy liền.','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT507','SV1','入境停留超期，前往出入境大厅办理逾期说明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V507','SIT507','P1','twist','chinh_thuc',NULL,'外籍人员在华签证超期属于非法滞留，会根据超期天数罚款，多次逾期会被限制入境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_01','V507','阮明',1,'警官您好，我上次出境旅游延误返程，在境内停留超期五天。','jǐng guān nín hǎo， wǒ shàng cì chū jìng lǚ yóu yán wù fǎn chéng， zài jìng nèi tíng liú chāo qī wǔ tiān。','Chào anh công an, lần trước tôi đi du lịch nước ngoài bị hoãn chuyến về, nên đã ở lại trong nước quá hạn năm ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_02','V507','民警',2,'先说明超期原因，提供机票行程单、学校在读证明吧。','xiān shuō míng chāo qī yuán yīn， tí gōng jī piào xíng chéng dān、 xué xiào zài dú zhèng míng ba。','Trước tiên trình bày lý do quá hạn, cung cấp hành trình vé máy bay và giấy xác nhận đang học tại trường nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_03','V507','阮明',3,'航班大面积延误导致无法按时离境，机票行程单在这里。','háng bān dà miàn jī yán wù dǎo zhì wú fǎ àn shí lí jìng， jī piào xíng chéng dān zài zhè lǐ。','Do chuyến bay bị hoãn trên diện rộng nên không thể xuất cảnh đúng hạn, hành trình vé máy bay đây ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_04','V507','民警',4,'短期超期十五天内可书面说明，超过十五天处罚会加重嘛。','duǎn qī chāo qī shí wǔ tiān nèi kě shū miàn shuō míng， chāo guò shí wǔ tiān chǔ fá huì jiā zhòng ma。','Quá hạn ngắn trong vòng mười lăm ngày thì có thể viết bản tường trình, quá mười lăm ngày thì mức phạt sẽ nặng hơn đó.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_05','V507','阮明',5,'本次超期会留下不良记录，影响下次续签居留吗？','běn cì chāo qī huì liú xià bù liáng jì lù， yǐng xiǎng xià cì xù qiān jū liú ma？','Lần quá hạn này có để lại tiền án tiền sự gì không, có ảnh hưởng đến việc gia hạn cư trú lần sau không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_06','V507','民警',6,'如实说明客观原因且首次违规，记录不会严重影响续签。','rú shí shuō míng kè guān yuán yīn qiě shǒu cì wéi guī， jì lù bú huì yán zhòng yǐng xiǎng xù qiān。','Nếu trình bày trung thực lý do khách quan và đây là vi phạm lần đầu thì hồ sơ sẽ không ảnh hưởng nghiêm trọng đến việc gia hạn đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_07','V507','阮明',7,'需要手写书面逾期情况说明，当场签字上交对吗？','xū yào shǒu xiě shū miàn yú qī qíng kuàng shuō míng， dāng chǎng qiān zì shàng jiāo duì ma？','Tôi cần viết tay bản tường trình về việc quá hạn, ký tên nộp ngay tại chỗ đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_08','V507','民警',8,'没错，写完核对信息签字，再缴纳对应逾期罚款即可。','méi cuò， xiě wán hé duì xìn xī qiān zì， zài jiǎo nà duì yìng yú qī fá kuǎn jí kě。','Đúng rồi, viết xong kiểm tra lại thông tin rồi ký tên, sau đó nộp khoản tiền phạt quá hạn tương ứng là xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_09','V507','阮明',9,'我马上书写说明，配合完成全部处理流程。','wǒ mǎ shàng shū xiě shuō míng， pèi hé wán chéng quán bù chǔ lǐ liú chéng。','Tôi viết bản tường trình ngay đây, sẽ phối hợp hoàn tất toàn bộ quy trình xử lý.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT508','SV1','咨询单人宿舍住宿登记如何录入居留系统',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V508','SIT508','P1','suon_se','tuy_y',NULL,'所有外籍居住人员必须完成住宿登记，校内宿舍由宿管开具登记证明，校外租房由房东陪同社区备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_01','V508','阮明',1,'阿姨，我住单人宿舍，住宿登记怎么录入签证系统呢？','ā yí， wǒ zhù dān rén sù shè， zhù sù dēng jì zěn me lù rù qiān zhèng xì tǒng ne？','Cô ơi, con ở phòng ký túc xá đơn, đăng ký lưu trú thì nhập vào hệ thống visa như thế nào ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_02','V508','宿管阿姨',2,'我这边给你打印住宿登记单，盖宿舍楼公章就行啦。','wǒ zhè biān gěi nǐ dǎ yìn zhù sù dēng jì dān， gài sù shè lóu gōng zhāng jiù xíng la。','Để cô in cho con tờ đăng ký lưu trú, rồi đóng dấu của tòa ký túc xá là xong nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_03','V508','阮明',3,'多人宿舍和单人宿舍的登记单据格式是一样的吗？','duō rén sù shè hé dān rén sù shè de dēng jì dān jù gé shì shì yī yàng de ma？','Mẫu đăng ký của phòng đơn với phòng nhiều người có giống nhau không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_04','V508','宿管阿姨',4,'单据通用，只需要在房间人数一栏填写单人。','dān jù tōng yòng， zhǐ xū yào zài fáng jiān rén shù yī lán tián xiě dān rén。','Mẫu dùng chung thôi, chỉ cần ghi số người trong phòng là một người là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_05','V508','阮明',5,'拿到登记单直接带去出入境大厅递交签证材料？','ná dào dēng jì dān zhí jiē dài qù chū rù jìng dà tīng dì jiāo qiān zhèng cái liào？','Con cầm tờ đăng ký này đi thẳng lên phòng xuất nhập cảnh nộp hồ sơ visa luôn được không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_06','V508','宿管阿姨',6,'对，这份单据是证明你合法住宿的核心材料。','duì， zhè fèn dān jù shì zhèng míng nǐ hé fǎ zhù sù de hé xīn cái liào。','Đúng rồi, đây là giấy tờ cốt lõi để chứng minh con lưu trú hợp pháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_07','V508','阮明',7,'麻烦您打印一份给我，我下午就去办居留申请。','má fán nín dǎ yìn yī fèn gěi wǒ， wǒ xià wǔ jiù qù bàn jū liú shēn qǐng。','Phiền cô in cho con một bản, chiều nay con đi làm thủ tục xin cư trú luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT509','SV2','居留许可快到期，提前咨询续办流程',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V509','SIT509','P1','suon_se','ban_chinh_thuc',NULL,'居留续签不能使用过期住宿登记、旧流水，所有辅助材料要求近期开具，保证信息实时有效。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_01','V509','阮明',1,'老师，我的居留许可还有四十天到期，想咨询续签流程。','lǎo shī， wǒ de jū liú xǔ kě hái yǒu sì shí tiān dào qī， xiǎng zī xún xù qiān liú chéng。','Thầy ơi, giấy phép cư trú của em còn bốn mươi ngày nữa là hết hạn, em muốn hỏi về thủ tục gia hạn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_02','V509','老师',2,'第一步先开在校在读证明，再准备银行存款流水哦。','dì yī bù xiān kāi zài xiào zài dú zhèng míng， zài zhǔn bèi yín háng cún kuǎn liú shuǐ ó。','Bước đầu tiên em xin giấy xác nhận đang học tại trường, sau đó chuẩn bị sao kê tiền gửi ngân hàng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_03','V509','阮明',3,'存款流水有最低金额要求吗，需要存多久的记录？','cún kuǎn liú shuǐ yǒu zuì dī jīn é yāo qiú ma， xū yào cún duō jiǔ de jì lù？','Sao kê tiền gửi có yêu cầu số tiền tối thiểu không thầy, cần lưu bao lâu ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_04','V509','老师',4,'留学生建议提供至少一万元、连续三个月以上流水。','liú xué shēng jiàn yì tí gōng zhì shǎo yī wàn yuán、 lián xù sān gè yuè yǐ shàng liú shuǐ。','Du học sinh nên có tối thiểu một vạn tệ, sao kê liên tục từ ba tháng trở lên.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_05','V509','阮明',5,'住宿登记单还要重新打印，上次办签证的旧单据能用吗？','zhù sù dēng jì dān hái yào chóng xīn dǎ yìn， shàng cì bàn qiān zhèng de jiù dān jù néng yòng ma？','Tờ đăng ký lưu trú có cần in lại không thầy, tờ cũ dùng khi làm visa lần trước còn dùng được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_06','V509','老师',6,'续签需要近一个月内新开具的住宿登记证明，旧的失效。','xù qiān xū yào jìn yí gè yuè nèi xīn kāi jù de zhù sù dēng jì zhèng míng， jiù de shī xiào。','Gia hạn thì cần giấy đăng ký lưu trú mới cấp trong vòng một tháng gần đây, tờ cũ hết hiệu lực rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_07','V509','阮明',7,'材料备齐后，线上预约出入境办理号就可以递交？','cái liào bèi qí hòu， xiàn shàng yù yuē chū rù jìng bàn lǐ hào jiù kě yǐ dì jiāo？','Sau khi chuẩn bị đủ giấy tờ, em đặt lịch online lấy số ở phòng xuất nhập cảnh rồi nộp luôn được chứ ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_08','V509','老师',8,'线上预约优先办理，无预约只能现场排队等候。','xiàn shàng yù yuē yōu xiān bàn lǐ， wú yù yuē zhǐ néng xiàn chǎng pái duì děng hòu。','Đặt lịch online được ưu tiên xử lý trước, không đặt lịch thì chỉ có thể xếp hàng tại chỗ thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_09','V509','阮明',9,'我会提前整理全部材料，避免临近到期手忙脚乱。','wǒ huì tí qián zhěng lǐ quán bù cái liào， bì miǎn lín jìn dào qī shǒu máng jiǎo luàn。','Em sẽ chuẩn bị sẵn hết giấy tờ từ sớm, tránh gần đến hạn mà cuống lên.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT510','SV2','续签证时银行存款证明余额不足，需重新开流水',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V510','SIT510','P1','that_bai_nhe','chinh_thuc',NULL,'留学生续签居留许可有活期存款最低额度要求，出入境只认可活期账户流水，定期、理财不计入审核余额。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_01','V510','阮明',1,'您好，我递交居留续签材料，麻烦帮忙核对一下。','nín hǎo， wǒ dì jiāo jū liú xù qiān cái liào， má fán bāng máng hé duì yī xià。','Xin chào, tôi nộp hồ sơ gia hạn cư trú, phiền anh/chị kiểm tra giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_02','V510','工作人员',2,'这份银行流水月末余额不足一万元，达不到签证标准。','zhè fèn yín háng liú shuǐ yuè mò yú é bù zú yī wàn yuán， dá bú dào qiān zhèng biāo zhǔn。','Số dư cuối tháng trên sao kê ngân hàng này chưa đủ một vạn tệ, không đạt tiêu chuẩn visa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_03','V510','阮明',3,'我卡里有定期存款，能不能把定期存单一起当作资产证明？','wǒ kǎ lǐ yǒu dìng qī cún kuǎn， néng bù néng bǎ dìng qī cún dān yì qǐ dàng zuò zī chǎn zhèng míng？','Tôi có khoản tiền gửi có kỳ hạn, có thể dùng sổ tiết kiệm đó làm chứng minh tài sản cùng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_04','V510','工作人员',4,'系统只认可活期流水实时余额，定期存单不能抵扣要求嘛。','xì tǒng zhǐ rèn kě huó qī liú shuǐ shí shí yú é， dìng qī cún dān bù néng dǐ kòu yāo qiú ma。','Hệ thống chỉ chấp nhận số dư thực tế của tài khoản không kỳ hạn, tiền gửi có kỳ hạn không được tính vào yêu cầu này.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_05','V510','阮明',5,'那我转入资金后，隔天再来打印新流水重新递交可以吗？','nà wǒ zhuǎn rù zī jīn hòu， gé tiān zài lái dǎ yìn xīn liú shuǐ chóng xīn dì jiāo kě yǐ ma？','Vậy sau khi tôi chuyển tiền vào, hôm sau quay lại in sao kê mới rồi nộp lại được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_06','V510','工作人员',6,'可以，资金到账次日打印流水，余额达标再重新取号办理。','kě yǐ， zī jīn dào zhàng cì rì dǎ yìn liú shuǐ， yú é dá biāo zài chóng xīn qǔ hào bàn lǐ。','Được, hôm sau tiền vào tài khoản thì in sao kê, số dư đạt chuẩn rồi lấy số làm lại thủ tục.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_07','V510','阮明',7,'今天先把其余材料带回，明天补足资金重新打印流水。','jīn tiān xiān bǎ qí yú cái liào dài huí， míng tiān bǔ zú zī jīn chóng xīn dǎ yìn liú shuǐ。','Hôm nay tôi mang các giấy tờ còn lại về trước, mai bổ sung đủ tiền rồi in lại sao kê.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_08','V510','工作人员',8,'记得流水打印当日不要大额转出资金。','jì de liú shuǐ dǎ yìn dāng rì bú yào dà é zhuǎn chū zī jīn。','Nhớ là ngày in sao kê thì đừng chuyển khoản số tiền lớn ra ngoài nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_09','V510','阮明',9,'明白了，感谢告知存款流水审核标准。','míng bái le， gǎn xiè gào zhī cún kuǎn liú shuǐ shěn hé biāo zhǔn。','Tôi hiểu rồi, cảm ơn đã cho biết tiêu chuẩn xét duyệt sao kê tiền gửi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT511','SV2','在校出勤率不够，学校不给开具签证在读证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V511','SIT511','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内高校对留学生出勤有硬性考核，出勤率不达标学校有权拒开在读证明，无法办理居留续签，严重者会要求限期离境。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_01','V511','阮明',1,'辅导员您好，我需要在读证明办理居留续签，麻烦帮我开具。','fǔ dǎo yuán nín hǎo， wǒ xū yào zài dú zhèng míng bàn lǐ jū liú xù qiān， má fán bāng wǒ kāi jù。','Chào cô cố vấn, em cần giấy xác nhận đang học để làm thủ tục gia hạn cư trú, phiền cô cấp giúp em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_02','V511','辅导员',2,'系统显示你本学期旷课次数超标，出勤率未达到学校标准。','xì tǒng xiǎn shì nǐ běn xué qī kuàng kè cì shù chāo biāo， chū qín lǜ wèi dá dào xué xiào biāo zhǔn。','Hệ thống hiển thị học kỳ này em nghỉ học vượt quá số buổi cho phép, tỷ lệ chuyên cần chưa đạt chuẩn của trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_03','V511','阮明',3,'前段时间身体不舒服请假缺课，全部有医院病假单留存。','qián duàn shí jiān shēn tǐ bù shū fú qǐng jià quē kè， quán bù yǒu yī yuàn bìng jià dān liú cún。','Thời gian trước em bị ốm nên xin nghỉ học, tất cả đều có giấy nghỉ ốm của bệnh viện lưu lại ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_04','V511','辅导员',4,'病假需要提前报备学院，事后补交单据不计入合规请假记录嘛。','bìng jià xū yào tí qián bào bèi xué yuàn， shì hòu bǔ jiāo dān jù bù jì rù hé guī qǐng jià jì lù ma。','Nghỉ ốm cần báo trước cho khoa, nộp giấy tờ bổ sung sau thì không được tính vào diện nghỉ phép hợp lệ đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_05','V511','阮明',5,'那现在有什么办法可以补全出勤记录，拿到在读证明？','nà xiàn zài yǒu shén me bàn fǎ kě yǐ bǔ quán chū qín jì lù， ná dào zài dú zhèng míng？','Vậy bây giờ có cách nào để bổ sung đủ số buổi chuyên cần, để lấy được giấy xác nhận đang học không cô?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_06','V511','辅导员',6,'接下来一个月全程不缺课，月末核查出勤后才能开具证明。','jiē xià lái yí gè yuè quán chéng bù quē kè， yuè mò hé chá chū qín hòu cái néng kāi jù zhèng míng。','Một tháng tới em không được nghỉ buổi nào, cuối tháng kiểm tra chuyên cần đạt thì mới cấp giấy xác nhận được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_07','V511','阮明',7,'我的签证马上到期，延迟开证明会导致签证断签啊。','wǒ de qiān zhèng mǎ shàng dào qī， yán chí kāi zhèng míng huì dǎo zhì qiān zhèng duàn qiān a。','Visa của em sắp hết hạn rồi, chậm cấp giấy này thì sẽ bị gián đoạn visa mất ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_08','V511','辅导员',8,'我给你开临时情况说明，先去出入境申请短期缓冲受理。','wǒ gěi nǐ kāi lín shí qíng kuàng shuō míng， xiān qù chū rù jìng shēn qǐng duǎn qī huǎn chōng shòu lǐ。','Cô sẽ viết cho em giấy giải trình tình huống tạm thời, em cứ ra phòng xuất nhập cảnh xin xử lý gia hạn tạm thời trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_09','V511','阮明',9,'太感谢您帮忙协调，我之后一定准时上课不缺勤。','tài gǎn xiè nín bāng máng xié tiáo， wǒ zhī hòu yí dìng zhǔn shí shàng kè bù quē qín。','Em cảm ơn cô rất nhiều vì đã giúp em, sau này em nhất định sẽ đi học đúng giờ, không nghỉ nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT512','SV2','咨询寒暑假居留延期是否需要额外材料',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V512','SIT512','P1','suon_se','tuy_y',NULL,'留学生寒暑假留校，续签必须额外提交加盖学院公章的留校申请，证明假期在校学习安排。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_01','V512','阮明',1,'警官，寒暑假不回国，续居留和学期内续签材料一样吗？','jǐng guān， hán shǔ jià bù huí guó， xù jū liú hé xué qī nèi xù qiān cái liào yī yàng ma？','Chú công an ơi, kỳ nghỉ hè đông không về nước thì hồ sơ gia hạn cư trú có giống hồ sơ gia hạn trong học kỳ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_02','V512','辅警',2,'大体材料相同，额外需要一份假期留校申请书哈。','dà tǐ cái liào xiāng tóng， é wài xū yào yī fèn jià qī liú xiào shēn qǐng shū hā。','Về cơ bản giấy tờ giống nhau, chỉ cần thêm một đơn xin ở lại trường trong kỳ nghỉ thôi nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_03','V512','阮明',3,'留校申请书手写就可以，还是必须打印盖章？','liú xiào shēn qǐng shū shǒu xiě jiù kě yǐ， hái shì bì xū dǎ yìn gài zhāng？','Đơn xin ở lại trường viết tay được không, hay bắt buộc phải in ra?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_04','V512','辅警',4,'打印填写后学院国际处盖章，手写无公章无效。','dǎ yìn tián xiě hòu xué yuàn guó jì chù gài zhāng， shǒu xiě wú gōng zhāng wú xiào。','In ra điền xong rồi đem lên phòng quốc tế của trường đóng dấu, viết tay không có con dấu thì không hợp lệ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_05','V512','阮明',5,'假期留校居留有效期也是一年，还是只给到开学？','jià qī liú xiào jū liú yǒu xiào qī yě shì yī nián， hái shì zhǐ gěi dào kāi xué？','Thời hạn cư trú khi ở lại trường dịp nghỉ cũng là một năm, hay chỉ được cấp đến khi khai giảng thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_06','V512','辅警',6,'统一按学制发放一年有效期，不受寒暑假限制。','tǒng yī àn xué zhì fā fàng yī nián yǒu xiào qī， bù shòu hán shǔ jià xiàn zhì。','Cấp thống nhất theo thời gian học là một năm, không bị giới hạn bởi kỳ nghỉ hè đông đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_07','V512','阮明',7,'清楚了，我回去打印申请书找老师盖章。','qīng chǔ le， wǒ huí qù dǎ yìn shēn qǐng shū zhǎo lǎo shī gài zhāng。','Con rõ rồi ạ, con về in đơn rồi nhờ thầy cô đóng dấu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT513','SV2','校外租房居住，房东不配合办理住宿登记单',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V513','SIT513','P1','twist','ban_chinh_thuc',NULL,'出租房屋房东有法定义务配合外籍租客完成社区住宿备案，拒不配合社区可依法约谈整改。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_01','V513','阮明',1,'网格员您好，我在外租房办签证需要住宿登记，房东不肯配合。','wǎng gé yuán nín hǎo， wǒ zài wài zū fáng bàn qiān zhèng xū yào zhù sù dēng jì， fáng dōng bù kěn pèi hé。','Chào anh tổ trưởng dân phố, em thuê nhà ở ngoài, cần làm đăng ký lưu trú để làm visa nhưng chủ nhà không chịu hợp tác.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_02','V513','网格员',2,'先跟我说一下房东拒绝配合的具体原因是什么呢？','xiān gēn wǒ shuō yī xià fáng dōng jù jué pèi hé de jù tǐ yuán yīn shì shén me ne？','Em nói cho anh nghe cụ thể lý do chủ nhà từ chối hợp tác là gì được không?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_03','V513','阮明',3,'房东说登记要上交房产证复印件，担心信息泄露不愿意提供。','fáng dōng shuō dēng jì yào shàng jiāo fáng chǎn zhèng fù yìn jiàn， dān xīn xìn xī xiè lòu bù yuàn yì tí gōng。','Chủ nhà bảo đăng ký phải nộp bản photo sổ đỏ, sợ lộ thông tin nên không muốn cung cấp ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_04','V513','网格员',4,'外籍租客住宿备案是法定要求，房东有义务配合登记嘛。','wài jí zū kè zhù sù bèi àn shì fǎ dìng yāo qiú， fáng dōng yǒu yì wù pèi hé dēng jì ma。','Đăng ký lưu trú cho người thuê nhà nước ngoài là quy định pháp luật bắt buộc, chủ nhà có nghĩa vụ phải hợp tác đăng ký chứ.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_05','V513','阮明',5,'如果房东始终拒绝到场备案，我还有别的办理渠道吗？','rú guǒ fáng dōng shǐ zhōng jù jué dào chǎng bèi àn， wǒ hái yǒu bié de bàn lǐ qú dào ma？','Nếu chủ nhà cứ từ chối có mặt làm đăng ký, em còn kênh nào khác để xử lý không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_06','V513','网格员',6,'我上门和房东沟通劝导，沟通无果会下发书面告知单。','wǒ shàng mén hé fáng dōng gōu tōng quàn dǎo， gōu tōng wú guǒ huì xià fā shū miàn gào zhī dān。','Anh sẽ đến tận nơi trao đổi thuyết phục chủ nhà, nếu không đạt được kết quả thì sẽ gửi văn bản thông báo chính thức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_07','V513','阮明',7,'今天您能联系房东上门办理，我现在在出租屋等候。','jīn tiān nín néng lián xì fáng dōng shàng mén bàn lǐ， wǒ xiàn zài zài chū zū wū děng hòu。','Hôm nay anh có thể liên hệ chủ nhà đến làm việc không, giờ em đang ở nhà thuê chờ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_08','V513','网格员',8,'半小时内到房屋现场，携带备案表格、拍照留存房屋信息。','bàn xiǎo shí nèi dào fáng wū xiàn chǎng， xié dài bèi àn biǎo gé、 pāi zhào liú cún fáng wū xìn xī。','Nửa tiếng nữa anh có mặt tại căn nhà, mang theo biểu mẫu đăng ký, chụp ảnh lưu lại thông tin nhà ở.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_09','V513','阮明',9,'麻烦您出面协调，没有登记单我没法续办居留签证。','má fán nín chū miàn xié tiáo， méi yǒu dēng jì dān wǒ méi fǎ xù bàn jū liú qiān zhèng。','Phiền anh ra mặt giúp em thu xếp, không có tờ đăng ký thì em không thể làm thủ tục gia hạn visa được.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT514','SV2','续居留预约号约满，咨询线下现场取号方案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V514','SIT514','P1','twist','tuy_y',NULL,'出入境线上预约号资源紧张，线下应急号数量有限，仅针对签证续签人群，新办居留不开放线下现场号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_01','V514','阮明',1,'你好，线上预约系统近七天的续签号全部约满了。','nǐ hǎo， xiàn shàng yù yuē xì tǒng jìn qī tiān de xù qiān hào quán bù yuē mǎn le。','Chào bạn, hệ thống đặt lịch online trong bảy ngày tới đã hết số gia hạn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_02','V514','引导员',2,'线上号源每日定时发放抢号，线下保留少量应急现场号哦。','xiàn shàng hào yuán měi rì dìng shí fā fàng qiǎng hào， xiàn xià bǎo liú shǎo liàng yìng jí xiàn chǎng hào ó。','Số online phát theo giờ cố định mỗi ngày, còn có một ít số khẩn cấp tại chỗ dự phòng đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_03','V514','阮明',3,'现场号几点开始发放，需要一早来排队等候吗？','xiàn chǎng hào jǐ diǎn kāi shǐ fā fàng， xū yào yī zǎo lái pái duì děng hòu ma？','Số tại chỗ phát từ mấy giờ vậy, có phải đến xếp hàng từ sáng sớm không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_04','V514','引导员',4,'早上八点大厅开门发放当日现场号，发完即止不追加。','zǎo shàng bā diǎn dà tīng kāi mén fā fàng dāng rì xiàn chǎng hào， fā wán jí zhǐ bù zhuī jiā。','Tám giờ sáng sảnh mở cửa phát số tại chỗ trong ngày, phát hết là ngừng, không phát thêm đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_05','V514','阮明',5,'现场号只受理续签业务，首次办居留不能用现场号对吧？','xiàn chǎng hào zhǐ shòu lǐ xù qiān yè wù， shǒu cì bàn jū liú bù néng yòng xiàn chǎng hào duì ba？','Số tại chỗ chỉ giải quyết nghiệp vụ gia hạn thôi đúng không, làm cư trú lần đầu thì không dùng được số tại chỗ phải không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_06','V514','引导员',6,'没错，首次居留只能线上预约，续签才有应急线下号。','méi cuò， shǒu cì jū liú zhǐ néng xiàn shàng yù yuē， xù qiān cái yǒu yìng jí xiàn xià hào。','Đúng vậy, cư trú lần đầu chỉ đặt lịch online thôi, gia hạn thì mới có số khẩn cấp tại chỗ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_07','V514','阮明',7,'那我明天七点半过来排队抢当日现场办理号。','nà wǒ míng tiān qī diǎn bàn guò lái pái duì qiǎng dāng rì xiàn chǎng bàn lǐ hào。','Vậy mai bảy giờ rưỡi mình đến xếp hàng giành số xử lý tại chỗ trong ngày.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT515','SV2','签证办理期间护照上交，申请临时出行证明',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V515','SIT515','P1','suon_se','chinh_thuc',NULL,'护照上交出入境办理签证期间，无法乘坐交通、入住酒店，必须申请临时出行证明作为替代身份证件。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_01','V515','阮明',1,'您好，我的护照上交办理居留续签，周末需要短途出行。','nín hǎo， wǒ de hù zhào shàng jiāo bàn lǐ jū liú xù qiān， zhōu mò xū yào duǎn tú chū xíng。','Xin chào, tôi đang nộp hộ chiếu để làm thủ tục gia hạn cư trú, cuối tuần này tôi cần đi công tác ngắn ngày ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_02','V515','工作人员',2,'可以申请《外国人临时出行证明》，有效期七天呢。','kě yǐ shēn qǐng 《 wài guó rén lín shí chū xíng zhèng míng 》， yǒu xiào qī qī tiān ne。','Anh/chị có thể xin cấp Giấy chứng nhận đi lại tạm thời cho người nước ngoài, có hiệu lực trong bảy ngày ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_03','V515','阮明',3,'办理临时出行证明需要额外提交什么纸质材料？','bàn lǐ lín shí chū xíng zhèng míng xū yào é wài tí jiāo shén me zhǐ zhì cái liào？','Làm giấy chứng nhận đi lại tạm thời thì cần nộp thêm giấy tờ giấy gì nữa không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_04','V515','工作人员',4,'递交一张白底证件照，填写出行目的地即可。','dì jiāo yī zhāng bái dǐ zhèng jiàn zhào， tián xiě chū xíng mù dì dì jí kě。','Nộp một ảnh thẻ nền trắng, điền nơi đến là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_05','V515','阮明',5,'这份临时证明可以乘坐高铁、酒店入住正常使用吗？','zhè fèn lín shí zhèng míng kě yǐ chéng zuò gāo tiě、 jiǔ diàn rù zhù zhèng cháng shǐ yòng ma？','Giấy chứng nhận tạm thời này có thể dùng để đi tàu cao tốc, nhận phòng khách sạn bình thường không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_06','V515','工作人员',6,'国内交通、住宿全部通用，等同于临时身份证件。','guó nèi jiāo tōng、 zhù sù quán bù tōng yòng， děng tóng yú lín shí shēn fèn zhèng jiàn。','Dùng được cho cả giao thông và lưu trú trong nước, tương đương với giấy tờ tùy thân tạm thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_07','V515','阮明',7,'等下取办好的居留贴纸时，要同步归还临时证明吧？','děng xià qǔ bàn hǎo de jū liú tiē zhǐ shí， yào tóng bù guī huán lín shí zhèng míng ba？','Lát nữa khi lấy tem cư trú đã làm xong, tôi phải trả lại giấy chứng nhận tạm thời cùng lúc luôn phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_08','V515','工作人员',8,'是的，领取护照当日回收临时出行纸质证明。','shì de， lǐng qǔ hù zhào dāng rì huí shōu lín shí chū xíng zhǐ zhì zhèng míng。','Vâng, ngày nhận lại hộ chiếu thì sẽ thu hồi luôn giấy chứng nhận đi lại tạm thời bằng giấy đó ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_09','V515','阮明',9,'麻烦帮我同步办理，周末出行不用滞留市内了。','má fán bāng wǒ tóng bù bàn lǐ， zhōu mò chū xíng bù yòng zhì liú shì nèi le。','Phiền anh/chị xử lý đồng thời giúp tôi, để cuối tuần tôi có thể đi lại mà không phải ở lại trong thành phố ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT516','SV2','中途休学，咨询居留签证暂停与恢复手续',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V516','SIT516','P1','twist','chinh_thuc',NULL,'留学生休学、退学导致学籍失效，学生居留许可自动失效，需在规定缓冲期内离境，滞留会产生行政处罚。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_01','V516','阮明',1,'老师，我身体原因申请休学半年，想了解居留签证处理方式。','lǎo shī， wǒ shēn tǐ yuán yīn shēn qǐng xiū xué bàn nián， xiǎng liǎo jiě jū liú qiān zhèng chǔ lǐ fāng shì。','Thưa thầy/cô, vì lý do sức khỏe em xin nghỉ học nửa năm, em muốn tìm hiểu về cách xử lý visa cư trú ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_02','V516','老师',2,'休学期间学籍暂停，现有居留许可同步失效，需要限期离境。','xiū xué qī jiān xué jí zàn tíng， xiàn yǒu jū liú xǔ kě tóng bù shī xiào， xū yào xiàn qī lí jìng。','Trong thời gian bảo lưu, tư cách học sinh sẽ tạm ngừng, giấy phép cư trú hiện tại cũng đồng thời hết hiệu lực, em phải xuất cảnh trong thời hạn quy định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_03','V516','阮明',3,'不能办理临时居留留在国内休养，必须返回越南吗？','bù néng bàn lǐ lín shí jū liú liú zài guó nèi xiū yǎng， bì xū fǎn huí yuè nán ma？','Vậy không thể xin cư trú tạm thời để ở lại trong nước điều trị, bắt buộc phải về Việt Nam ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_04','V516','老师',4,'休学无有效在校学籍，不符合学生居留审批标准嘛。','xiū xué wú yǒu xiào zài xiào xué jí， bù fú hé xué shēng jū liú shěn pī biāo zhǔn ma。','Bảo lưu học tập nghĩa là không còn tư cách học sinh hợp lệ, nên không đáp ứng tiêu chuẩn xét duyệt cư trú diện học sinh đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_05','V516','阮明',5,'半年后复学返校，重新办居留要从头提交全套材料？','bàn nián hòu fù xué fǎn xiào， chóng xīn bàn jū liú yào cóng tóu tí jiāo quán tào cái liào？','Sau nửa năm quay lại học, khi xin cư trú lại có phải nộp lại toàn bộ hồ sơ từ đầu không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_06','V516','老师',6,'复学后凭复学通知书，按新生流程重新申请居留许可。','fù xué hòu píng fù xué tōng zhī shū， àn xīn shēng liú chéng chóng xīn shēn qǐng jū liú xǔ kě。','Khi quay lại học, em dùng giấy thông báo phục học, làm thủ tục xin cư trú lại theo quy trình như học sinh mới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_07','V516','阮明',7,'休学手续办完后，给我几天缓冲时间收拾行李离境？','xiū xué shǒu xù bàn wán hòu， gěi wǒ jǐ tiān huǎn chōng shí jiān shōu shí xíng lǐ lí jìng？','Sau khi hoàn tất thủ tục bảo lưu, thầy/cô cho em mấy ngày để thu xếp hành lý rồi xuất cảnh ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_08','V516','老师',8,'休学备案当日起，给予三十天合法停留缓冲期。','xiū xué bèi àn dāng rì qǐ， jǐ yǔ sān shí tiān hé fǎ tíng liú huǎn chōng qī。','Kể từ ngày đăng ký bảo lưu, em được gia hạn lưu trú hợp pháp thêm ba mươi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_09','V516','阮明',9,'我清楚规则了，会在缓冲期内安排回国休养。','wǒ qīng chǔ guī zé le， huì zài huǎn chōng qī nèi ān pái huí guó xiū yǎng。','Em đã rõ quy định rồi, em sẽ sắp xếp về nước điều trị trong thời gian gia hạn đó.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT517','SV2','短期出境旅游，咨询居留证是否需要备案',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V517','SIT517','P1','suon_se','tuy_y',NULL,'持有有效长期学生居留许可，短期出境旅游无需向出入境报备，仅毕业、休学、永久离境才需要注销备案。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_01','V517','阮明',1,'警官，我下周出境旅游，有效居留证需要提前备案吗？','jǐng guān， wǒ xià zhōu chū jìng lǚ yóu， yǒu xiào jū liú zhèng xū yào tí qián bèi àn ma？','Chào anh công an, tuần sau em đi du lịch nước ngoài, thẻ cư trú còn hiệu lực thì có cần đăng ký trước không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_02','V517','辅警',2,'短期出国旅游不用线下备案，居留有效期内自由往返哈。','duǎn qī chū guó lǚ yóu bù yòng xiàn xià bèi àn， jū liú yǒu xiào qī nèi zì yóu wǎng fǎn hā。','Đi du lịch ngắn ngày thì không cần đăng ký trực tiếp đâu, trong thời hạn cư trú thì cứ tự do đi lại thôi.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_03','V517','阮明',3,'出境的时候只需要同时出示护照和居留贴纸对吧？','chū jìng de shí hòu zhǐ xū yào tóng shí chū shì hù zhào hé jū liú tiē zhǐ duì ba？','Lúc xuất cảnh em chỉ cần xuất trình hộ chiếu và tem cư trú cùng lúc đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_04','V517','辅警',4,'对，两样证件一并交给海关查验即可。','duì， liǎng yàng zhèng jiàn yī bìng jiāo gěi hǎi guān chá yàn jí kě。','Đúng rồi, đưa cả hai giấy tờ cho hải quan kiểm tra là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_05','V517','阮明',5,'如果出境超过一个月，回来签证会不会受影响？','rú guǒ chū jìng chāo guò yí gè yuè， huí lái qiān zhèng huì bú huì shòu yǐng xiǎng？','Nếu em đi quá một tháng, lúc về visa có bị ảnh hưởng gì không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_06','V517','辅警',6,'只要居留没到期，无论出境时长都不影响入境。','zhǐ yào jū liú méi dào qī， wú lùn chū jìng shí cháng dōu bù yǐng xiǎng rù jìng。','Chỉ cần cư trú chưa hết hạn thì dù đi bao lâu cũng không ảnh hưởng đến việc nhập cảnh lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_07','V517','阮明',7,'明白了，不用额外跑大厅办理出境报备。','míng bái le， bù yòng é wài pǎo dà tīng bàn lǐ chū jìng bào bèi。','Em hiểu rồi, vậy không cần chạy lên sảnh làm thủ tục báo xuất cảnh gì thêm ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT518','SV3','护照丢失，派出所开遗失证明用于补办签证',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V518','SIT518','P1','suon_se','chinh_thuc',NULL,'外籍护照遗失必须先到派出所报案获取回执，无回执无法办理临时通行证明、新护照。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_01','V518','阮明',1,'警官您好，我的越南护照丢失，前来开具遗失报案回执。','jǐng guān nín hǎo， wǒ de yuè nán hù zhào diū shī， qián lái kāi jù yí shī bào àn huí zhí。','Chào anh công an, em bị mất hộ chiếu Việt Nam, em đến xin biên nhận báo mất ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_02','V518','民警',2,'详细说明丢失时间、路线、随身携带的全部物品吧。','xiáng xì shuō míng diū shī shí jiān、 lù xiàn、 suí shēn xié dài de quán bù wù pǐn ba。','Em nói rõ thời gian mất, lộ trình di chuyển và toàn bộ đồ đạc mang theo lúc đó đi.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_03','V518','阮明',3,'昨天下午商圈逛街，结账后口袋内护照连同钱包一同遗失。','zuó tiān xià wǔ shāng quān guàng jiē， jié zhàng hòu kǒu dài nèi hù zhào lián tóng qián bāo yī tóng yí shī。','Chiều hôm qua em đi dạo khu trung tâm mua sắm, sau khi thanh toán thì hộ chiếu cùng ví bị mất luôn trong túi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_04','V518','民警',4,'我制作遗失笔录，签字后打印两份报案回执给你留存。','wǒ zhì zuò yí shī bǐ lù， qiān zì hòu dǎ yìn liǎng fèn bào àn huí zhí gěi nǐ liú cún。','Anh lập biên bản mất giấy tờ, sau khi em ký thì anh in hai bản biên nhận báo mất để em giữ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_05','V518','阮明',5,'一份回执去出入境办临时通行，一份去大使馆补办护照对吗？','yī fèn huí zhí qù chū rù jìng bàn lín shí tōng xíng， yī fèn qù dà shǐ guǎn bǔ bàn hù zhào duì ma？','Một bản em mang lên phòng xuất nhập cảnh xin đi lại tạm thời, một bản gửi đại sứ quán xin cấp lại hộ chiếu, đúng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_06','V518','民警',6,'两份回执用途分开，务必妥善保管不能丢失。','liǎng fèn huí zhí yòng tú fēn kāi， wù bì tuǒ shàn bǎo guǎn bù néng diū shī。','Hai bản dùng cho hai việc khác nhau, em phải cất giữ cẩn thận, không được làm mất nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_07','V518','阮明',7,'没有这份报案回执，无法办理任何补办证件手续吧？','méi yǒu zhè fèn bào àn huí zhí， wú fǎ bàn lǐ rèn hé bǔ bàn zhèng jiàn shǒu xù ba？','Nếu không có biên nhận báo mất này thì không thể làm bất cứ thủ tục cấp lại giấy tờ nào đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_08','V518','民警',8,'没错，使馆与出入境均强制要求派出所遗失证明。','méi cuò， shǐ guǎn yǔ chū rù jìng jūn qiáng zhì yāo qiú pài chū suǒ yí shī zhèng míng。','Đúng vậy, cả đại sứ quán lẫn phòng xuất nhập cảnh đều bắt buộc phải có giấy xác nhận mất từ công an.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_09','V518','阮明',9,'辛苦您登记备案，证件丢失给大家添麻烦了。','xīn kǔ nín dēng jì bèi àn， zhèng jiàn diū shī gěi dà jiā tiān má fán le。','Cảm ơn anh đã ghi nhận giúp em, việc mất giấy tờ làm phiền mọi người quá.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT519','SV3','居留许可贴纸损毁模糊，申请换发居留贴纸',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V519','SIT519','P1','twist','ban_chinh_thuc',NULL,'居留贴纸磨损、撕毁、信息模糊属于证件损毁，必须换发，旧照片超出半年有效期不能用于新证件办理。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_01','V519','阮明',1,'您好，我护照上的居留贴纸磨损掉色，信息看不清了。','nín hǎo， wǒ hù zhào shàng de jū liú tiē zhǐ mó sǔn diào sè， xìn xī kàn bù qīng le。','Chào anh/chị, tem cư trú trên hộ chiếu của em bị mòn phai màu, không đọc rõ thông tin được nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_02','V519','工作人员',2,'贴纸损毁需要换发居留许可，先提交白底证件照哦。','tiē zhǐ sǔn huǐ xū yào huàn fā jū liú xǔ kě， xiān tí jiāo bái dǐ zhèng jiàn zhào ó。','Tem bị hỏng thì phải xin cấp lại giấy phép cư trú, trước tiên em nộp ảnh thẻ nền trắng nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_03','V519','阮明',3,'上次办签证的旧照片还有剩余，直接用旧照片可以吗？','shàng cì bàn qiān zhèng de jiù zhào piān hái yǒu shèng yú， zhí jiē yòng jiù zhào piān kě yǐ ma？','Lần trước làm visa em còn dư ảnh cũ, dùng ảnh cũ luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_04','V519','工作人员',4,'换发证件要求近六个月内新拍摄照片，旧照不予受理嘛。','huàn fā zhèng jiàn yāo qiú jìn liù gè yuè nèi xīn pāi shè zhào piān， jiù zhào bù yǔ shòu lǐ ma。','Cấp lại giấy tờ yêu cầu ảnh chụp trong vòng sáu tháng gần đây, ảnh cũ thì không được chấp nhận đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_05','V519','阮明',5,'楼下大厅自助拍照机可以当场拍摄签证专用照片吗？','lóu xià dà tīng zì zhù pāi zhào jī kě yǐ dāng chǎng pāi shè qiān zhèng zhuān yòng zhào piān ma？','Máy chụp ảnh tự động ở sảnh tầng dưới có chụp được ảnh chuyên dùng cho visa ngay tại chỗ không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_06','V519','工作人员',6,'可以，拍完直接带纸质照片回来取号办理换发。','kě yǐ， pāi wán zhí jiē dài zhǐ zhì zhào piān huí lái qǔ hào bàn lǐ huàn fā。','Được chứ, chụp xong em cầm ảnh giấy quay lại đây lấy số làm thủ tục cấp lại luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_07','V519','阮明',7,'换发期间护照需要上交，还是可以自行保管？','huàn fā qī jiān hù zhào xū yào shàng jiāo， hái shì kě yǐ zì xíng bǎo guǎn？','Trong thời gian cấp lại, hộ chiếu có phải nộp lại hay em tự giữ được ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_08','V519','工作人员',8,'全程留存护照七个工作日，如需出行办临时证明。','quán chéng liú cún hù zhào qī gè gōng zuò rì， rú xū chū xíng bàn lín shí zhèng míng。','Hộ chiếu sẽ được giữ lại suốt bảy ngày làm việc, nếu cần đi đâu thì làm giấy xác nhận tạm thời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_09','V519','阮明',9,'我现在去拍照，回来递交换发居留贴纸的材料。','wǒ xiàn zài qù pāi zhào， huí lái dì jiāo huàn fā jū liú tiē zhǐ de cái liào。','Vậy giờ em đi chụp ảnh, xong quay lại nộp hồ sơ đổi tem cư trú.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT520','SV3','护照补办完成后，重新补办在华居留许可',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V520','SIT520','P1','suon_se','chinh_thuc',NULL,'补办护照后不能直接沿用旧居留，必须同步补办居留贴纸，新旧护照搭配使用仅短期有效，长期必须换发居留。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_01','V520','阮明',1,'您好，我的新护照已经从使馆取回，补办丢失的居留许可。','nín hǎo， wǒ de xīn hù zhào yǐ jīng cóng shǐ guǎn qǔ huí， bǔ bàn diū shī de jū liú xǔ kě。','Chào anh/chị, em vừa lấy hộ chiếu mới từ đại sứ quán về, giờ em xin cấp lại giấy phép cư trú bị mất ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_02','V520','工作人员',2,'递交新护照、派出所遗失回执、在读证明、住宿登记单。','dì jiāo xīn hù zhào、 pài chū suǒ yí shī huí zhí、 zài dú zhèng míng、 zhù sù dēng jì dān。','Em nộp hộ chiếu mới, biên nhận báo mất của công an, giấy xác nhận đang học và phiếu đăng ký lưu trú nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_03','V520','阮明',3,'旧护照上过期的签证页复印件，也需要一并上交核对吗？','jiù hù zhào shàng guò qī de qiān zhèng yè fù yìn jiàn， yě xū yào yī bìng shàng jiāo hé duì ma？','Bản photo trang visa đã hết hạn trên hộ chiếu cũ có cần nộp kèm để đối chiếu không ạ?',NULL);
